definition.script:
pipeline {
    agent any

    stages {
        stage('1. Docker 버전 확인') {
            steps {
                // 젠킨스가 도커 CLI 명령어를 수행
                sh 'docker --version'
                sh 'docker ps'
            }
        }
        stage('2. 테스트 이미지 생성 및 실행') {
            steps {
                // 우분투 컨테이너를 임시로 띄워 테스트
                sh 'docker run --rm ubuntu:22.04 echo "Hello from Docker inside Jenkins!"'
            }
        }
    }
}
